INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (1, 129911, 6, 0, 0.8, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 6, 0, 11, 0, 6011);
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES ("", 0, "", "", "", "", 6, "", 91, "", 6012);
